// Anotação em variáveis: o tipo vem a seguir a dois pontos
const cidade: string = "Braga";
const habitantes: number = 193333;
const capitalDeDistrito: boolean = true;

// Anotação em parâmetros e no valor de retorno
function descrever(nome: string, populacao: number): string {
  return `${nome} tem ${populacao} habitantes.`;
}

console.log(descrever(cidade, habitantes)); // "Braga tem 193333 habitantes."
console.log(capitalDeDistrito); // true

// @ts-expect-error o parâmetro populacao é number e não aceita uma string
console.log(descrever(cidade, "193333"));

// Sem uma única anotação: o TypeScript deduz tudo
const cidade = "Braga";              // cidade: "Braga"
let habitantes = 193333;             // habitantes: number
const coordenadas = [41.55, -8.42];  // coordenadas: number[]
const morada = { rua: "Rua Nova", numero: 12 }; // { rua: string; numero: number }

// O tipo de retorno também é inferido a partir do return
function duplicar(valor: number) {   // retorno inferido: number
  return valor * 2;
}

habitantes = duplicar(habitantes);

console.log(cidade, habitantes); // "Braga" 386666
console.log(coordenadas.length, morada.numero); // 2 12

// 1. Parâmetros: o compilador não tem de onde os inferir
function aplicarDesconto(preco: number, percentagem: number): number {
  return preco - (preco * percentagem) / 100;
}

console.log(aplicarDesconto(100, 25)); // 75

// 2. Estruturas que nascem vazias e só depois são preenchidas
const carrinho: { artigo: string; preco: number }[] = [];
carrinho.push({ artigo: "Teclado", preco: 49.9 });

console.log(carrinho.length); // 1

const semAnotacao = {};
// @ts-expect-error o tipo de semAnotacao é {}, que não tem propriedade artigo
semAnotacao.artigo = "Rato";

// 3. Anotar documenta a intenção e apanha o erro no sítio certo
const precos: number[] = [10, 20, 30];

// @ts-expect-error o array é de number e não aceita a string "40"
precos.push("40");

const metodo = "POST"; // tipo inferido: "POST" (tipo literal)
let verbo = "POST";    // tipo inferido: string (o literal foi alargado)

verbo = "GET"; // permitido: qualquer string serve

function pedir(url: string, metodoHttp: "GET" | "POST"): string {
  return `${metodoHttp} ${url}`;
}

console.log(pedir("/clientes", metodo)); // "POST /clientes"

// @ts-expect-error verbo é string, e string não cabe em "GET" | "POST"
console.log(pedir("/clientes", verbo));

// Atenção: dentro de um objeto, mesmo declarado com const, as propriedades alargam
const config = { metodo: "POST" }; // config.metodo: string, não "POST"

// @ts-expect-error config.metodo é string porque a propriedade é mutável
console.log(pedir("/clientes", config.metodo));

const resposta: unknown = JSON.parse('{"nome":"Ana"}');

// Legítimo: sabemos algo que o compilador não pode saber
const utilizador = resposta as { nome: string };
console.log(utilizador.nome); // "Ana"

// as const: impede o alargamento e torna tudo só de leitura
const metodos = ["GET", "POST"] as const; // readonly ["GET", "POST"]
const definicoes = { timeout: 30 } as const; // { readonly timeout: 30 }

// @ts-expect-error um array readonly não tem push
metodos.push("PUT");

console.log(metodos[0], definicoes.timeout); // "GET" 30

// Perigoso: a assertion cala o compilador, não converte nada
const idade = "quarenta" as unknown as number;
console.log(typeof idade); // "string" — em memória continua a ser texto

let resultado = 42; // inferido: number, e assim fica até ao fim do âmbito

// @ts-expect-error resultado é number e nunca poderá guardar uma string
resultado = "quarenta e dois";

// O erro típico: reaproveitar a variável do valor lido para o valor convertido
let entrada = "10"; // inferido: string

// @ts-expect-error entrada é string e não aceita o número convertido
entrada = Number(entrada);

// Forma correta A: um nome novo para o valor convertido
const texto = "10";
const numero = Number(texto);

// Forma correta B: declarar desde o início os tipos que a variável vai ter
let campo: string | number = "10";
campo = 10;

console.log(numero, typeof campo); // 10 "number"

const ficheiros = ["indice.ts", "utils.ts"];
//    ^? const ficheiros: string[]

function contar(itens: string[]) {
  return itens.length;
}
//       ^? function contar(itens: string[]): number

const total = contar(ficheiros);
//    ^? const total: number

console.log(total); // 2

