const largura: number = 3;
const altura: number = 4;
const unidade: string = "m";

function area(l: number, a: number): number {
  return l * a;
}

function etiqueta(nome: string, valor: number, sufixo: string): string {
  return `${nome}: ${valor} ${sufixo}`;
}

console.log(etiqueta("Área", area(largura, altura), unidade)); // "Área: 12 m"

function descrever(estado: "pendente" | "enviado" | "entregue"): string {
  return `Encomenda ${estado}`;
}

const inicial = "pendente";     // const infere o tipo literal "pendente"
console.log(descrever(inicial)); // "Encomenda pendente"

let atual: "pendente" | "enviado" | "entregue" = "pendente";
atual = "entregue";
console.log(descrever(atual)); // "Encomenda entregue"

let solto = "pendente"; // let infere string
// @ts-expect-error string não é atribuível a "pendente" | "enviado" | "entregue"
console.log(descrever(solto));

const definicoes = { nivel: "info", tentativas: 3 } as const;
const definicoesSoltas = { nivel: "info", tentativas: 3 };

function registar(nivel: "debug" | "info" | "erro", mensagem: string): string {
  return `[${nivel}] ${mensagem}`;
}

console.log(registar(definicoes.nivel, "arranque")); // "[info] arranque"
console.log(definicoes.tentativas); // 3

// @ts-expect-error sem as const, a propriedade nivel foi alargada para string
console.log(registar(definicoesSoltas.nivel, "arranque"));

// @ts-expect-error as const torna todas as propriedades só de leitura
definicoes.tentativas = 5;
